mapper.select:
SELECT b.bi_idx, b.ui_idx, u.ui_name, b.bi_type, b.bi_title, b.bi_content, b.bi_category, b.bi_filename, b.bi_filepath, b.bi_refidx, CAST( ( SELECT COUNT(*) FROM board_recommend_info r WHERE r.bi_idx = b.bi_idx ) AS INTEGER ) AS recommend_count, b.time_created, b.time_modified FROM board_info b INNER JOIN user_info u ON b.ui_idx = u.ui_idx WHERE b.bi_type = 1
AND b.bi_title ILIKE '%' || #{searchKeyword} || '%'
AND b.bi_category = #{categoryCode}
AND ( SELECT COUNT(*) FROM board_recommend_info r WHERE r.bi_idx = b.bi_idx ) >= #{minRecommend}
ORDER BY b.bi_idx DESC
LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) FROM board_info b WHERE b.bi_type = 1
AND b.bi_title ILIKE '%' || #{searchKeyword} || '%'
AND b.bi_category = #{categoryCode}
AND ( SELECT COUNT(*) FROM board_recommend_info r WHERE r.bi_idx = b.bi_idx ) >= #{minRecommend}
